{
  "items": [
    {
      "title": "Historic Economic Data for Regions of the UK (1966–1996) – Office for National Statistics",
      "url_or_doi": "https://www.ons.gov.uk/economy/regionalaccounts/grossdisposablehouseholdincome/adhocs/006226historiceconomicdataforregionsoftheuk1966to1996",
      "justification": "An official UK dataset containing historical regional economic statistics, including GDP, household expenditure, disposable income, consumer spending, and capital formation. It covers 1990–1996 and is particularly useful for examining regional economic development, industrial restructuring, investment patterns, and economic disparities across the United Kingdom during the early and mid-1990s."
    },
    {
      "title": "British Household Panel Survey: Waves 1–18, 1991–2009 – UK Data Service",
      "url_or_doi": "https://doi.org/10.5255/UKDA-SN-5151-2",
      "justification": "A longitudinal household survey beginning in 1991 that provides detailed information about employment, household income, education, socioeconomic conditions, and changes in living standards. The 1991–1999 waves are especially relevant for studying the relationship between economic development, labour markets, income inequality, and household welfare in 1990s Britain. Access requires UK Data Service registration."
    },
    {
      "title": "World Development Indicators: United Kingdom – World Bank",
      "url_or_doi": "https://databank.worldbank.org/reports.aspx?country=GBR&series=NY.GDP.MKTP.KD.ZG&source=2",
      "justification": "The World Bank's World Development Indicators provide historical economic and development statistics for the United Kingdom, including GDP growth and other indicators available through the database. The 1990–1999 observations can be used to investigate economic growth, structural development, and macroeconomic performance. The data are particularly useful for comparing the United Kingdom with other developed economies during the 1990s."
    },
    {
      "title": "A Millennium of Macroeconomic Data for the UK – Bank of England",
      "url_or_doi": "https://www.bankofengland.co.uk/statistics/research-datasets.",
      "justification": "A comprehensive historical macroeconomic dataset published by the Bank of England. It includes long-run economic and financial indicators spanning the 1990s, making it valuable for investigating monetary conditions, inflation, economic growth, and broader changes in the UK's economic system. Its extensive historical coverage also allows researchers to compare the 1990s with earlier and later periods of economic development."
    },
    {
      "title": "Historical UK National Accounts – Economic Statistics Centre of Excellence",
      "url_or_doi": "https://www.escoe.ac.uk/research/historical-data/national-accounts-2/",
      "justification": "A collection of reconstructed historical UK national accounts covering 1948–1997, including national income and sector accounts. It provides detailed information for examining economic production, expenditure, institutional sectors, and structural change during most of the 1990s. Particularly valuable for studying the evolution of the UK's economic system using historical national accounting frameworks."
    },
    {
      "title": "Quarterly Labour Force Survey, 1992–2026: Secure Access – UK Data Service",
      "url_or_doi": "https://datacatalogue.ukdataservice.ac.uk/studies/study/6727",
      "justification": "An official labour market dataset containing information about employment, unemployment, economic inactivity, occupations, training, working hours, and individual characteristics. Its coverage beginning in 1992 makes it particularly useful for analysing labour market restructuring, unemployment trends, workforce development, and changes in employment patterns during the UK's economic recovery in the 1990s. Secure access requires additional approval."
    },
    {
      "title": "Family Expenditure Survey, 1994–1995 – UK Data Service",
      "url_or_doi": "https://datacatalogue.ukdataservice.ac.uk/datasets/dataset/05a146df-84ff-f87d-e426-810e04a22072",
      "justification": "A household expenditure dataset from the mid-1990s that supports research into consumption patterns, household economic circumstances, and differences in living standards. It is relevant for examining how economic conditions affected household spending and material welfare during a period of economic growth and structural change in the United Kingdom."
    },
    {
      "title": "General Household Survey, 1993–1994 – UK Data Archive",
      "url_or_doi": "https://b2find.eudat.eu/dataset/9d735a76-49d3-5547-b278-a42456937f31",
      "justification": "A household survey containing socioeconomic information, including employment, income, housing conditions, education, pensions, and financial circumstances. The 1993–1994 observations provide evidence about living standards and social development during the UK's recovery from the early-1990s recession. Suitable for studying the social consequences of economic change and differences across demographic groups."
    },
    {
      "title": "Historical Regional Economic Data – Economic Statistics Centre of Excellence",
      "url_or_doi": "https://www.escoe.ac.uk/research/historical-data/regional-data/",
      "justification": "A collection of regional economic datasets covering long periods of British economic history, including the 1990s. It brings together historical regional accounts, employment estimates, and other economic statistics. Particularly relevant for investigating regional economic inequalities, industrial change, geographical differences in productivity, and patterns of economic development across the United Kingdom."
    },
    {
      "title": "Historical Data Repository UK – Economic Statistics Centre of Excellence, Bank of England and ONS",
      "url_or_doi": "https://www.escoe.ac.uk/research/historical-data/",
      "justification": "A historical economic data repository developed with the Bank of England and the Office for National Statistics. It provides access to macroeconomic, financial, industrial, employment, and regional economic statistics, including historical series covering the 1990s. It is particularly valuable for research on changes in Britain's economic institutions, financial system, industrial structure, and long-term development."
    },
    {
      "title": "World Development Indicators: GDP Growth (Annual %) – United Kingdom",
      "url_or_doi": "https://data.worldbank.org/indicator/NY.GDP.MKTP.KD.ZG?downloadformat=csv&locations=GB",
      "justification": "An official World Bank economic indicator dataset providing annual real GDP growth rates for the United Kingdom, including observations from 1990 through 1999. It is directly relevant for analysing the early-1990s recession, subsequent economic recovery, and overall economic growth during the decade. The data can also support international comparisons of economic development and macroeconomic performance."
    }
  ]
}
